289	/** The coordinator's `runReplays` dependency: resolves task and setup ids, then runs them. */
290	export function replayRunner(deps: ReplayRunnerDeps): ToolBackend["runReplays"] {
291	  return async ({ plan_id, tasks: taskIds, setups: setupIds, max_cost_usd }) => {
292	    if (!deps.repo) throw new Error("no repo configured for replays");
293	    const f = await fetchCheckpoints(deps.repo, { cacheDir: deps.cacheDir });
294	    if (f.backend === "none") throw new Error("no Entire checkpoints found in this repo");
295	    const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch").map((s) => ({
296	      ...s,
297	      setup_id: identify(s, f.repoPath).setupId,
298	    }));
299	    const planned = new Map(planReplayTasks(f.repoPath, sessions, []).tasks.map((t) => [t.id, t]));
300	    const missingTasks = taskIds.filter((t) => !planned.has(t));
301	    if (missingTasks.length) throw new Error(`no replayable task for session(s) ${missingTasks.join(", ")}`);
302	    const known = new Map(loadSetups(deps.setupsRoot ?? process.cwd(), deps.env ?? process.env).map((s) => [s.id, s]));
303	    const missingSetups = setupIds.filter((s) => !known.has(s));
304	    if (missingSetups.length) throw new Error(`unknown setup(s) ${missingSetups.join(", ")}`);
305	
306	    const skipped: SkippedRun[] = [];
307	    const replays = await runReplays({
308	      repo: f.repoPath,
309	      tasks: taskIds.map((t) => planned.get(t)!),
310	      setups: setupIds.map((s) => known.get(s)!),
311	      workRoot: deps.workRoot ?? defaultWorkRoot(),
312	      parallel: deps.parallel,
313	      maxCostUsd: max_cost_usd,
314	      harness: deps.harness,
315	      testCmd: deps.testCmd,
316	      planId: plan_id,
317	      onSkip: (s) => skipped.push(s),
318	    });
319	    const cost_usd = replays.reduce((s, r) => s + (r.cost_usd ?? 0), 0);
320	    return { replays, cost_usd, skipped } as ReplayBatch;
321	  };
322	}
