324	export async function runReplays(opts: RunReplaysOptions): Promise<Replay[]> {
325	  const workRoot = resolve(opts.workRoot);
326	  if (underHome(workRoot)) throw new Error(`workRoot ${workRoot} is under $HOME; replays must run outside it`);
327	  mkdirSync(workRoot, { recursive: true });
328	  const bin = writeSettingSourcesShim(join(workRoot, "bin"), opts.claudeBin);
329	  const o = { ...opts, workRoot, harness: opts.harness ?? runClaude, bin };
330	  const skip = (task: string, setup: string, reason: string) => opts.onSkip?.({ task, setup, reason });
331	
332	  const queue: Array<{ task: ReplayTask; setup: RunnableSetup; order: number }> = [];
333	  for (const task of opts.tasks) {
334	    for (const setup of opts.setups) {
335	      const why = unavailable(setup);
336	      if (why) skip(task.id, setup.id, why);
337	      else queue.push({ task, setup, order: queue.length });
338	    }
339	  }
340	
341	  const out: Array<{ order: number; replay: Replay }> = [];
342	  let spent = 0;
343	  let next = 0;
344	  const worker = async () => {
345	    while (next < queue.length) {
346	      const job = queue[next++]!;
347	      const left = opts.maxCostUsd - spent;
348	      if (left <= 0) {
349	        skip(job.task.id, job.setup.id, `budget: spent $${spent.toFixed(4)} of $${opts.maxCostUsd}`);
350	        continue;
351	      }
352	      const replay = await runOne(o, job.task, job.setup, Math.min(opts.perRunUsd ?? DEFAULT_PER_RUN_USD, left));
353	      spent += replay.cost_usd ?? 0;
354	      out.push({ order: job.order, replay });
355	    }
356	  };
357	  const n = Math.max(1, Math.floor(opts.parallel ?? DEFAULT_PARALLEL));
358	  await Promise.all(Array.from({ length: Math.min(n, queue.length) }, worker));
359	  return out.sort((a, b) => a.order - b.order).map((x) => x.replay);
360	}
